#!/usr/bin/env sh
# fetch STCP — Sociedade de Transportes Colectivos do Porto (PT) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://dadosabertos.cm-porto.pt/dataset/71490e40-9e19-11f1-84ed-6abdb6d5cf34/resource/94ad1662-e033-4ccf-b63c-8806f124c3dc/download/gtfs_feed.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
